"""L300 lesson 12 (python raft.py): a simplified Raft replicated log on 3 in-process nodes over a deterministic
simulated network (helpers.Network, driven by helpers.Cluster). Terms, leader election, log replication, commit index, leader crash and
re-election, then the failure lab: a follower with a stale log wins an election. Simplified: no disk, no
snapshots, no membership changes, no PreVote. Seeded: identical output on every run."""
import random

from helpers import Cluster, demo, fmt

HEARTBEAT, TIMEOUT = 3, (10, 20)  # ticks; each node draws its election timeout from a seeded RNG


class Node:
    def __init__(self, name, peers, net, seed):
        self.name, self.peers, self.net, self.rng = name, peers, net, random.Random(f"{seed}-{name}")
        self.term, self.voted_for, self.log = 0, None, []  # persistent state; log[i-1] = (term, command)
        self.commit, self.role, self.votes = 0, "follower", set()  # volatile state
        self.reset_timer()

    def reset_timer(self):
        self.deadline = self.net.now + self.rng.randint(*TIMEOUT)  # randomized timeout: split votes stay rare

    def last(self):
        return (self.log[-1][0] if self.log else 0), len(self.log)  # (last log term, last log index)

    def tick(self):
        if self.role == "leader":
            if self.net.now % HEARTBEAT == 0:
                for p in self.peers:
                    self.send_append(p)  # heartbeat = AppendEntries, carries new entries if any
        elif self.net.now >= self.deadline:  # heard no leader for a whole timeout: new term, vote for me
            self.term, self.role, self.voted_for, self.votes = self.term + 1, "candidate", self.name, {self.name}
            self.reset_timer()
            last_term, last_index = self.last()
            self.net.log(f"{self.name} starts election for term {self.term} (log {fmt(self.log)})")
            for p in self.peers:
                self.net.send(self.name, p, {"type": "vote", "term": self.term, "last_term": last_term, "last_index": last_index})

    def send_append(self, p):
        prev = self.next[p] - 1  # consistency check: the follower must hold my entry at prev
        self.net.send(self.name, p, {"type": "append", "term": self.term, "prev_index": prev,
                                     "prev_term": self.log[prev - 1][0] if prev else 0,
                                     "entries": self.log[prev:], "commit": self.commit})

    def propose(self, command):  # client request; only the leader appends (Leader Append-Only)
        self.log.append((self.term, command))
        for p in self.peers:
            self.send_append(p)

    def receive(self, src, m):
        if m["term"] > self.term:  # terms are a logical clock: a newer term turns anyone into a follower
            self.term, self.role, self.voted_for = m["term"], "follower", None
        kind, reply = m["type"], {"term": self.term}
        if kind == "vote":
            # RequestVote: one vote per term, first come first served. (Raft also checks the candidate's log.)
            granted = m["term"] == self.term and self.voted_for in (None, src)
            if granted:
                self.voted_for = src
                self.reset_timer()
            self.net.send(self.name, src, {**reply, "type": "vote_reply", "granted": granted})
        elif kind == "vote_reply" and self.role == "candidate" and m["term"] == self.term and m["granted"]:
            self.votes.add(src)
            if 2 * len(self.votes) > len(self.peers) + 1:  # majority of the FULL cluster (2 of 3)
                self.role, self.next, self.match = "leader", {p: len(self.log) + 1 for p in self.peers}, {p: 0 for p in self.peers}
                self.net.log(f"{self.name} becomes leader for term {self.term} with votes {sorted(self.votes)}")
                for p in self.peers:
                    self.send_append(p)
        elif kind == "append":
            ok = m["term"] == self.term
            if ok:
                self.role = "follower"
                self.reset_timer()  # a live leader for my term: no election
                prev = m["prev_index"]
                ok = prev <= len(self.log) and (prev == 0 or self.log[prev - 1][0] == m["prev_term"])
            if ok:
                for i, entry in enumerate(m["entries"], start=prev + 1):
                    if i <= len(self.log) and self.log[i - 1][0] != entry[0]:
                        del self.log[i - 1:]  # conflict: drop my entry and everything after it
                    if i > len(self.log):
                        self.log.append(entry)
                reply["match"] = prev + len(m["entries"])
                self.commit = max(self.commit, min(m["commit"], reply["match"]))  # learn the commit index
            self.net.send(self.name, src, {**reply, "type": "append_reply", "ok": ok})
        elif kind == "append_reply" and self.role == "leader" and m["term"] == self.term:
            if m["ok"]:
                self.match[src], self.next[src] = m["match"], m["match"] + 1
                for n in range(len(self.log), self.commit, -1):  # commit index: highest N on a majority ...
                    if self.log[n - 1][0] == self.term and 2 * (1 + sum(v >= n for v in self.match.values())) > len(self.peers) + 1:
                        self.commit = n  # ... from MY term only (paper section 5.4.2)
                        break
            else:
                self.next[src] = max(1, self.next[src] - 1)  # walk back until the logs match
                self.send_append(src)


def stale_leader_scenario(node_class=Node, seed=7):
    """Failure lab: a follower misses committed entries, the leader crashes, the stale follower's timer fires first."""
    c = Cluster(node_class, seed)
    leader = c.run_until_leader()
    follower, stale = [n for n in c.nodes if n != leader.name]
    c.crash(stale)  # stale is down (or partitioned) while the others commit
    leader.propose("x=1")
    leader.propose("x=2")
    c.run(6)
    c.crash(leader.name)
    c.restart(stale)
    c.nodes[stale].deadline = c.net.now + 1  # fault: stale's randomized timer happens to fire first
    c.run_until_leader().propose("x=9")
    c.run(12)
    return c


if __name__ == "__main__":
    demo(Node, stale_leader_scenario)  # helpers.demo: happy path, crash + re-election, restart, failure lab

"""L300 lesson 13 (python partition.py): fault injection with a Toxiproxy-style proxy. Three nodes reach the
lease store (lesson 7) and a shared register ("storage") only through the proxy. Happy path: one leader serves
client writes and reads. Fault: a partition cuts n1 off the lease store; n2 takes the lease and for a while
TWO nodes believe they lead and both write. The client history is printed as JSON lines and checked for
linearizability (checker.py). Seeded, simulated ticks: identical output on every run."""
import random

from checker import check_register, describe, stale_reads
from helpers import LeaseStore, jsonl

TTL = 3.0


class Timeout(Exception):
    pass


class Proxy:
    """Toxiproxy concepts: a link per (src, dst); 'down' (enabled=false) and 'drop' (toxicity) lose the request,
    'latency' delays it. A lost request is a Timeout to the caller: it cannot tell 'down' from 'slow'."""
    def __init__(self, seed=13):
        self.rng, self.toxics = random.Random(seed), {}

    def add(self, src, dst, **toxic):
        self.toxics.setdefault((src, dst), {}).update(toxic)

    def partition(self, side_a, side_b):
        for a in side_a:
            for b in side_b:
                self.add(a, b, down=True)
                self.add(b, a, down=True)

    def heal(self):
        self.toxics.clear()

    def call(self, src, dst, fn, *args):
        t = self.toxics.get((src, dst), {})
        if t.get("down") or self.rng.random() < t.get("drop", 0.0):
            raise Timeout(f"{src}->{dst}")
        return fn(*args), t.get("latency", 0.0)


class Storage:
    """The shared register every leader writes. (Build task: make it check fencing tokens.)"""
    def __init__(self):
        self.value, self.writes = 0, []

    def write(self, token, value):
        self.value = value
        self.writes.append((token, value))
        return "accepted"

    def read(self, token):
        return self.value


class Node:
    def __init__(self, name, proxy, lease, storage, log):
        self.name, self.proxy, self.lease, self.storage, self.log = name, proxy, lease, storage, log
        self.token, self.cache = None, None  # cache: leaders answer reads locally while they hold the lease

    def step(self, now):  # once per tick: renew my lease, or try to take a free one
        try:
            if self.token is None:
                (ok, token), _ = self.proxy.call(self.name, "lease", self.lease.acquire, self.name, now, TTL)
                if ok:
                    self.token = token
                    self.cache, _ = self.proxy.call(self.name, "storage", self.storage.read, token)
                    self.log(f"t={now} {self.name} acquired the lease, token {token}, loaded value {self.cache}")
            else:
                (ok, _) = self.proxy.call(self.name, "lease", self.lease.renew, self.name, self.token, now, TTL)
                if not ok:
                    self.log(f"t={now} {self.name} renew refused -> steps down")
                    self.token = None
        except Timeout as e:
            if self.token is not None:  # no answer is not a "no": n1 keeps believing it leads
                self.log(f"t={now} {self.name} renew timed out ({e}) -> still thinks it leads")

    def handle(self, now, process, f, value):
        op = {"process": process, "node": self.name, "f": f, "value": value, "start": now, "end": now + 0.5, "ok": False}
        if self.token is None:
            op["error"] = "not leader"
        elif f == "read":
            op.update(value=self.cache, ok=True)  # local read: fast, and only correct if I really still lead
        else:
            try:
                result, latency = self.proxy.call(self.name, "storage", self.storage.write, self.token, value)
                op["end"] += latency
                if result == "accepted":
                    self.cache, op["ok"] = value, True
            except Timeout as e:
                op["error"] = str(e)
        return op


def run(ops, faults, seed=13, ticks=11, storage=None):
    """ops: {tick: (process, node, f, value)}; faults: {tick: callable(proxy)}. Returns events, history, leaders."""
    proxy, lease, storage, events, history, leaders = Proxy(seed), LeaseStore(), storage or Storage(), [], [], []
    nodes = {n: Node(n, proxy, lease, storage, events.append) for n in ("n1", "n2", "n3")}
    for t in range(ticks):
        if t in faults:
            events.append(f"t={t} fault: {faults[t](proxy)}")
        for node in nodes.values():
            node.step(t)
        leaders.append(sorted(n.name for n in nodes.values() if n.token is not None))
        if t in ops:
            process, node, f, value = ops[t]
            history.append(nodes[node].handle(t, process, f, value))
    return events, history, leaders


OPS = {1: ("c1", "n1", "write", 1), 6: ("c2", "n2", "write", 2), 7: ("c1", "n1", "write", 3), 8: ("c2", "n2", "read", None)}
FAULTS = {2: lambda p: (p.partition({"n1"}, {"lease"}), p.add("n1", "storage", latency=0.3), "partition n1 | lease store; latency 0.3 n1->storage")[2],
          9: lambda p: (p.heal(), "heal")[1]}

if __name__ == "__main__":
    events, history, leaders = run(OPS, {})
    print("happy path (no faults): leaders per tick", " ".join("+".join(l) or "-" for l in leaders))
    print("  linearizable:", check_register(history)[0])
    events, history, leaders = run(OPS, FAULTS)
    print("\n".join(events))
    print("leaders per tick:", " ".join(f"{t}:{'+'.join(l) or '-'}" for t, l in enumerate(leaders)))
    print("history (JSON lines):", *jsonl(history), sep="\n  ")
    print("linearizable:", check_register(history)[0])
    for read, write in stale_reads(history):
        print(f"  stale read: {describe(read)}, but {describe(write)} had already finished")

"""L300 lesson 14 (python saga.py): an order saga across three services - orders, payments, shipping - each
owning its own data (no shared database, no distributed transaction). An orchestrator runs the steps in order
and records each one in a saga log (JSON lines). Happy path: every order ships. Fault (seeded): the shipping
service has no courier slot for some orders. Watch what the lesson code does with the money."""
import random

from helpers import SagaLog, StepFailed


class Orders:
    def __init__(self):
        self.status, self.amount = {}, {}

    def create(self, saga, amount):
        self.status[saga], self.amount[saga] = "PENDING", amount

    def cancel(self, saga, amount):  # compensation for create
        self.status[saga] = "CANCELLED"


class Payments:
    def __init__(self):
        self.ledger = []  # (saga, +amount) for a charge, (saga, -amount) for a refund

    def charge(self, saga, amount):  # idempotency key = saga id (lesson 5): a retried charge is a no-op
        if not any(s == saga and a > 0 for s, a in self.ledger):
            self.ledger.append((saga, amount))

    def refund(self, saga, amount):  # compensation for charge (semantic undo: a new entry, not a delete)
        self.ledger.append((saga, -amount))

    def net(self, saga):
        return sum(a for s, a in self.ledger if s == saga)


class Shipping:
    def __init__(self, fail_rate=0.0, seed=14):
        self.rng, self.fail_rate, self.outcome = random.Random(seed), fail_rate, {}

    def ship(self, saga, amount):  # the last step: once it succeeds the saga cannot be undone (pivot)
        if saga not in self.outcome:  # idempotent: decide once per saga, a retry gets the same answer
            failed = self.rng.random() < self.fail_rate  # fault injection: seeded -> same orders fail every run
            self.outcome[saga] = "no courier slot" if failed else "shipped"
        if self.outcome[saga] != "shipped":
            raise StepFailed(self.outcome[saga])

    @property
    def shipped(self):
        return {s for s, o in self.outcome.items() if o == "shipped"}


class Orchestrator:
    def __init__(self, orders, payments, shipping, log):
        self.orders, self.payments, self.log = orders, payments, log
        self.steps = [("create", orders.create, orders.cancel), ("charge", payments.charge, payments.refund),
                      ("ship", shipping.ship, None)]  # (step, action, compensating action)

    def run(self, saga, amount):
        self.log.write(saga, "saga", "started", amount=amount)
        for name, action, _compensation in self.steps:
            try:
                action(saga, amount)
            except StepFailed as e:
                self.log.write(saga, name, "failed", error=str(e))
                self.orders.status[saga] = "FAILED"  # tell the customer ... and keep their money?
                return "failed"
            self.log.write(saga, name, "done")
        self.orders.status[saga] = "APPROVED"
        self.log.write(saga, "saga", "completed")
        return "completed"


def audit(orders, payments, shipping):
    """Invariant, checked from each service's own data: a shipped order is APPROVED and paid in full; an order
    that did not ship is not APPROVED and the shop keeps none of its money. Returns the violations."""
    bad = []
    for s, status in sorted(orders.status.items()):
        shipped = s in shipping.shipped
        if payments.net(s) != (orders.amount[s] if shipped else 0) or (status == "APPROVED") != shipped:
            bad.append(f"{s}: {status}, shipped={shipped}, money kept={payments.net(s)} of {orders.amount[s]}")
    return bad


def run_orders(n=6, fail_rate=0.0, seed=14, orchestrator_class=Orchestrator):
    services = Orders(), Payments(), Shipping(fail_rate, seed)
    log = SagaLog()
    orch = orchestrator_class(*services, log)
    results = {f"o{i}": orch.run(f"o{i}", 10 * i) for i in range(1, n + 1)}
    return results, services, log, orch


if __name__ == "__main__":
    results, services, log, _ = run_orders()
    print("happy path:", results, "| audit:", audit(*services) or "OK")
    results, services, log, _ = run_orders(fail_rate=0.3)
    print("fault (30% of shipments fail, seed 14):", results)
    failed = [s for s, r in results.items() if r != "completed"]
    print(f"saga log of {failed[0]} (JSON lines):", *(l for l in log.lines if f'"{failed[0]}"' in l), sep="\n  ")
    print("audit:", *(audit(*services) or ["OK"]), sep="\n  ")
